<?php
declare(strict_types=1);
final class CharacterController{
private const VOCATIONS=['knight'=>'Cavaleiro','sorcerer'=>'Feiticeiro','druid'=>'Druida','ranger'=>'Patrulheiro'];
public static function index():void{$u=require_auth();$q=db()->prepare('SELECT c.id,c.name,c.level,v.name vocation FROM characters c JOIN vocations v ON v.code=c.vocation_code WHERE c.user_id=? ORDER BY c.created_at');$q->execute([$u['id']]);$rows=$q->fetchAll();$f=consume_flash();ob_start();?><section class="wrap"><small>SUA CONTA</small><h1>Seus personagens</h1><p class="muted">Escolha um aventureiro ou comece uma nova história.</p><?php if($f):?><div class="notice"><?=e($f['message'])?></div><?php endif;?><div class="cards"><?php foreach($rows as $c):?><article class="card"><b>✧</b><h2><?=e($c['name'])?></h2><p><?=e($c['vocation'])?> · Nível <?=(int)$c['level']?></p><a class="button primary" href="/game?character=<?=(int)$c['id']?>">Entrar no mundo</a></article><?php endforeach;?><article class="card"><b>＋</b><h2>Novo aventureiro</h2><a class="button secondary" href="/characters/create">Criar personagem</a></article></div></section><?php render('Personagens',(string)ob_get_clean());}
public static function create():void{$u=require_auth();if($_SERVER['REQUEST_METHOD']==='GET'){ob_start();?><section class="auth"><div class="panel"><small>FORJE SEU DESTINO</small><h1>Criar personagem</h1><?php $f=consume_flash();if($f):?><div class="notice"><?=e($f['message'])?></div><?php endif;?><form method="post" class="stack"><?=csrf_field()?><label>Nome<input name="name" minlength="3" maxlength="20" required></label><label>Vocação<select name="vocation"><?php foreach(self::VOCATIONS as $code=>$name):?><option value="<?=e($code)?>"><?=e($name)?></option><?php endforeach;?></select></label><button class="button primary">Criar personagem</button></form></div></section><?php render('Criar personagem',(string)ob_get_clean());return;}verify_csrf();$name=trim((string)($_POST['name']??''));$voc=(string)($_POST['vocation']??'');if(!preg_match('/^[\p{L}0-9 ]{3,20}$/u',$name)||!isset(self::VOCATIONS[$voc])){flash('Nome ou vocação inválidos.','error');redirect('/characters/create');}$q=db()->prepare('SELECT COUNT(*) FROM characters WHERE user_id=?');$q->execute([$u['id']]);if((int)$q->fetchColumn()>=3){flash('Limite de 3 personagens por conta.','error');redirect('/characters');}try{$q=db()->prepare('INSERT INTO characters(user_id,name,vocation_code,level,experience,health,mana,map_code,tile_x,tile_y,created_at,updated_at) SELECT ?,?,?,1,0,base_health,base_mana,\'elarion\',8,8,UTC_TIMESTAMP(),UTC_TIMESTAMP() FROM vocations WHERE code=?');$q->execute([$u['id'],$name,$voc,$voc]);flash('Personagem criado.','success');redirect('/characters');}catch(PDOException $e){flash('Nome indisponível. Tente outro.','error');redirect('/characters/create');}}
public static function game():void{$u=require_auth();$id=filter_input(INPUT_GET,'character',FILTER_VALIDATE_INT);$q=db()->prepare('SELECT c.*,v.name vocation,v.base_health max_health,v.base_mana max_mana FROM characters c JOIN vocations v ON v.code=c.vocation_code WHERE c.id=? AND c.user_id=? LIMIT 1');$q->execute([(int)$id,$u['id']]);$c=$q->fetch();if(!$c)redirect('/characters');ob_start();?><section class="wrap"><div class="game-head"><div><small>CONTINENTE DE ELARION</small><h1><?=e($c['name'])?></h1><p><?=e($c['vocation'])?> · Nível <?=(int)$c['level']?></p></div><a href="/characters">Trocar personagem</a></div><div class="stage"><canvas id="world" width="960" height="600" aria-label="Mapa isométrico de Elarion"></canvas><div class="overlay">MOVIMENTO: WASD OU SETAS · POSIÇÃO SALVA AUTOMATICAMENTE</div></div><div class="game-controls" aria-label="Controles de movimento"><button type="button" data-move="0,-1" aria-label="Mover para cima">▲</button><div><button type="button" data-move="-1,0" aria-label="Mover para esquerda">◀</button><button type="button" data-move="0,1" aria-label="Mover para baixo">▼</button><button type="button" data-move="1,0" aria-label="Mover para direita">▶</button></div></div><p id="save-status" class="save-status" role="status">Conectado ao mundo</p><div class="stats"><div>VIDA<strong><?=(int)$c['health']?> / <?=(int)$c['max_health']?></strong></div><div>MANA<strong><?=(int)$c['mana']?> / <?=(int)$c['max_mana']?></strong></div><div>EXPERIÊNCIA<strong><?=(int)$c['experience']?> XP</strong></div></div><p class="muted">Você pode caminhar pelo vale. O progresso de posição é salvo na sua conta.</p></section><script>window.AETHORIA_WORLD=<?=json_encode(['x'=>(int)$c['tile_x'],'y'=>(int)$c['tile_y'],'character'=>(int)$c['id'],'csrf'=>csrf_token(),'name'=>$c['name']],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;</script><script src="/assets/js/game.js" defer></script><?php render('Mundo',(string)ob_get_clean());}
public static function move():void{$u=require_auth();header('Content-Type: application/json; charset=utf-8');if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'Método não permitido']);return;}$token=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!is_string($token)||!hash_equals(csrf_token(),$token)){http_response_code(419);echo json_encode(['ok'=>false,'message'=>'Sessão expirada']);return;}$data=json_decode((string)file_get_contents('php://input'),true);$id=filter_var($data['character']??null,FILTER_VALIDATE_INT);$x=filter_var($data['x']??null,FILTER_VALIDATE_INT);$y=filter_var($data['y']??null,FILTER_VALIDATE_INT);if(!$id||$x===false||$y===false||$x<0||$x>=18||$y<0||$y>=15){http_response_code(422);echo json_encode(['ok'=>false,'message'=>'Posição inválida']);return;}$q=db()->prepare('UPDATE characters SET tile_x=?,tile_y=?,updated_at=UTC_TIMESTAMP() WHERE id=? AND user_id=?');$q->execute([$x,$y,$id,$u['id']]);if($q->rowCount()===0){$check=db()->prepare('SELECT id FROM characters WHERE id=? AND user_id=?');$check->execute([$id,$u['id']]);if(!$check->fetch()){http_response_code(404);echo json_encode(['ok'=>false,'message'=>'Personagem não encontrado']);return;}}echo json_encode(['ok'=>true,'x'=>$x,'y'=>$y]);}
}